/**
 * Sprint 7-8: "Next 5 videos" recommendations — pure, deterministic.
 *
 * Given one published video (topic + performance) and a pool of candidate
 * ideas (the user's saved/generated ideas from the P3 idea engine), score
 * each candidate and return the top 5 with a human-readable reason.
 *
 * Scoring is deliberately explainable — every point is traceable to a
 * real signal (topic overlap, proven hook reuse, outlier score, safety
 * fit). Nothing is generated by an LLM here, so nothing needs a disclaimer
 * about hallucination; the reasons say exactly why each idea was picked.
 */

export interface SourceVideo {
  title: string;
  topic: string;
  /** Verbatim opener of the first 3 seconds, when known. */
  hook?: string | null;
  views: number;
  /** Impression CTR 0-100, when known. */
  ctr?: number | null;
  /** Avg retention 0-100, when known. */
  retentionPct?: number | null;
  style?: string | null;
}

export type IdeaSafety = "safe" | "caution" | "risky";

export interface CandidateIdea {
  id: string;
  title: string;
  hook: string;
  angle: string;
  format: "short" | "long";
  difficulty: "easy" | "medium" | "hard";
  safetyFlag: IdeaSafety;
  /** Outlier multiple vs channel median, when the idea came from outliers. */
  outlierScore?: number | null;
  status: "new" | "saved" | "dismissed" | "used";
}

export interface VideoRecommendation {
  idea: CandidateIdea;
  score: number;
  reasons: string[];
}

export interface NextVideosResult {
  hasData: boolean;
  recommendations: VideoRecommendation[];
}

export const NEXT_VIDEOS_COUNT = 5;

/** Lowercase word tokens, stopwords removed, min length 3. */
const STOPWORDS = new Set([
  "the", "and", "for", "with", "you", "your", "this", "that", "from",
  "how", "why", "what", "when", "are", "was", "were", "will", "can",
  "has", "have", "had", "but", "not", "all", "our", "its", "who",
]);

function tokens(text: string): Set<string> {
  return new Set(
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .filter((w) => w.length >= 3 && !STOPWORDS.has(w)),
  );
}

function overlapSize(a: Set<string>, b: Set<string>): number {
  let n = 0;
  for (const w of a) if (b.has(w)) n++;
  return n;
}

/**
 * Score one candidate against the source video. Returns null when the
 * candidate is ineligible (dismissed or already used).
 */
export function scoreCandidate(
  source: SourceVideo,
  candidate: CandidateIdea,
): VideoRecommendation | null {
  if (candidate.status === "dismissed" || candidate.status === "used") return null;

  const reasons: string[] = [];
  let score = 0;

  // 1. Topic overlap with the source video's topic + title (weight 3/pt).
  const sourceTokens = tokens(`${source.topic} ${source.title}`);
  const candTokens = tokens(`${candidate.title} ${candidate.angle}`);
  const topicOverlap = overlapSize(sourceTokens, candTokens);
  if (topicOverlap > 0) {
    score += topicOverlap * 3;
    reasons.push(`Shares ${topicOverlap} topic keyword${topicOverlap === 1 ? "" : "s"} with “${source.title}”.`);
  }

  // 2. Reuses the source video's proven hook pattern (weight 2/pt).
  if (source.hook) {
    const hookOverlap = overlapSize(tokens(source.hook), tokens(candidate.hook));
    if (hookOverlap >= 2) {
      score += hookOverlap * 2;
      reasons.push("Reuses the opener pattern that worked on the source video.");
    }
  }

  // 3. Idea already proved itself as an outlier (weight = score, capped).
  const out = candidate.outlierScore ?? 0;
  if (out >= 2) {
    const pts = Math.min(10, out);
    score += pts;
    reasons.push(`Outperformed its channel median ${out.toFixed(1)}x.`);
  }

  // 4. Safety fit: penalize risky ideas when the source played it safe.
  if (candidate.safetyFlag === "risky") {
    score -= 4;
    reasons.push("Flagged risky for advertisers — review before producing.");
  } else if (candidate.safetyFlag === "safe") {
    score += 1;
  }

  // 5. Prefer ideas the user already saved (revealed preference).
  if (candidate.status === "saved") {
    score += 2;
    reasons.push("You already saved this idea.");
  }

  // 6. Easy wins first: small bonus for low production difficulty.
  if (candidate.difficulty === "easy") score += 1;

  if (reasons.length === 0) {
    reasons.push("General fit — no strong signal from the source video.");
  }

  return { idea: candidate, score, reasons };
}

/**
 * Recommend the next videos after a published one. Deduplicates near-
 * identical titles (Jaccard ≥ 0.8 on tokens) keeping the higher score.
 * Returns hasData: false when there is nothing to recommend from.
 */
export function recommendNextVideos(
  source: SourceVideo,
  candidates: CandidateIdea[],
  count: number = NEXT_VIDEOS_COUNT,
): NextVideosResult {
  const scored: VideoRecommendation[] = [];
  for (const c of candidates) {
    const r = scoreCandidate(source, c);
    if (r) scored.push(r);
  }
  if (scored.length === 0) {
    return { hasData: false, recommendations: [] };
  }

  scored.sort((a, b) => b.score - a.score || a.idea.title.localeCompare(b.idea.title));

  // Dedup near-identical titles.
  const picked: VideoRecommendation[] = [];
  for (const r of scored) {
    const rTokens = tokens(r.idea.title);
    const dup = picked.some((p) => {
      const pTokens = tokens(p.idea.title);
      const inter = overlapSize(rTokens, pTokens);
      const union = new Set([...rTokens, ...pTokens]).size;
      return union > 0 && inter / union >= 0.8;
    });
    if (!dup) picked.push(r);
    if (picked.length >= count) break;
  }

  return { hasData: true, recommendations: picked };
}
